class LinkedList:
    def __init__(self):
        self.head = None
        self.n = 0
    def append(self, v):
        node = Node(v)
        if self.head is None:
            self.head = node
        else:
            cur = self.head
            while cur.nxt is not None:
                cur = cur.nxt
            cur.nxt = node
        self.n += 1
    def to_list(self):
        out = []
        cur = self.head
        while cur is not None:
            out.append(cur.v)
            cur = cur.nxt
        return out
    def has(self, v):
        cur = self.head
        while cur is not None:
            if cur.v == v:
                return True
            cur = cur.nxt
        return False
